const markTrackCreditsScanned = `-- name: MarkTrackCreditsScanned :exec
INSERT INTO track_credit_scans (file_id, scanned_at)
VALUES ($1, NOW())
ON CONFLICT (file_id) DO UPDATE SET scanned_at = NOW()
`

func (q *Queries) MarkTrackCreditsScanned(ctx context.Context, fileID uuid.UUID) error {
	_, err := q.db.Exec(ctx, markTrackCreditsScanned, fileID)
	return err
}

const setAnalyzedReplayGain = `-- name: SetAnalyzedReplayGain :execrows
UPDATE media_files
SET replaygain_track_gain = $2,
    replaygain_track_peak = $3,
    replaygain_album_gain = $4,
    replaygain_album_peak = $5,
    replaygain_source     = 'analyzed'
WHERE id = $1
  AND (replaygain_source IS NULL OR replaygain_source = 'analyzed')
`

type SetAnalyzedReplayGainParams struct {
	ID                  uuid.UUID      `json:"id"`
	ReplaygainTrackGain pgtype.Numeric `json:"replaygain_track_gain"`
	ReplaygainTrackPeak pgtype.Numeric `json:"replaygain_track_peak"`
	ReplaygainAlbumGain pgtype.Numeric `json:"replaygain_album_gain"`
	ReplaygainAlbumPeak pgtype.Numeric `json:"replaygain_album_peak"`
}

// Writes measured ReplayGain values into the same columns tag values live
// in, so every client's normalisation picks them up. Refuses a file whose
// values came from tags (zero rows): a tag is never overwritten.
func (q *Queries) SetAnalyzedReplayGain(ctx context.Context, arg SetAnalyzedReplayGainParams) (int64, error) {
	result, err := q.db.Exec(ctx, setAnalyzedReplayGain,
		arg.ID,
		arg.ReplaygainTrackGain,
		arg.ReplaygainTrackPeak,
		arg.ReplaygainAlbumGain,
		arg.ReplaygainAlbumPeak,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const trackCreditsScanned = `-- name: TrackCreditsScanned :one
SELECT EXISTS (SELECT 1 FROM track_credit_scans WHERE file_id = $1)::boolean
`

func (q *Queries) TrackCreditsScanned(ctx context.Context, fileID uuid.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, trackCreditsScanned, fileID)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

const upsertFileLoudness = `-- name: UpsertFileLoudness :exec
INSERT INTO media_file_loudness (
    file_id, integrated_lufs, true_peak, duration_ms, file_size, file_hash, error, analyzed_at
) VALUES (
    $1, $2, $3, $4, $5, $6, $7, NOW()
)
ON CONFLICT (file_id) DO UPDATE
SET integrated_lufs = EXCLUDED.integrated_lufs,
    true_peak       = EXCLUDED.true_peak,
    duration_ms     = EXCLUDED.duration_ms,
    file_size       = EXCLUDED.file_size,
    file_hash       = EXCLUDED.file_hash,
    error           = EXCLUDED.error,
    analyzed_at     = NOW()
`

type UpsertFileLoudnessParams struct {
	FileID         uuid.UUID      `json:"file_id"`
	IntegratedLufs pgtype.Numeric `json:"integrated_lufs"`
	TruePeak       pgtype.Numeric `json:"true_peak"`
	DurationMs     *int64         `json:"duration_ms"`
	FileSize       int64          `json:"file_size"`
	FileHash       *string        `json:"file_hash"`
	Error          *string        `json:"error"`
}

// Records one measurement (or the reason there is none). file_size and
// file_hash are the file as measured; see media_file_loudness.
func (q *Queries) UpsertFileLoudness(ctx context.Context, arg UpsertFileLoudnessParams) error {
	_, err := q.db.Exec(ctx, upsertFileLoudness,
		arg.FileID,
		arg.IntegratedLufs,
		arg.TruePeak,
		arg.DurationMs,
		arg.FileSize,
		arg.FileHash,
		arg.Error,
	)
	return err
}

